\label{T_Population_size} Let conditions (\ref{MainAssump}) be valid for $ 
\alpha \in (0,1)$ and assumption (\ref{Def_phi}) hold true. Then, for any $ 
\lambda >0$

1) if $m\rightarrow \infty $ and $m=o(n)$ then 
\begin{equation*}
\lim_{n\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda (1-f_{m}(0))Z(m)}| 
\mathcal{H}(n,\varphi (n))\right] =\frac{1}{\left( 1+\lambda ^{\alpha
}\right) ^{1/\alpha +1}};
\end{equation*}

2) if $m\sim \theta n$ for some $\theta \in (0,1)$ then 
\begin{equation*}
\lim_{n\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda (1-f_{m}(0))Z(m)}| 
\mathcal{H}(n,\varphi (n))\right] =\frac{1}{\left( 1-\theta +\left( \lambda
\left( 1-\theta \right) ^{1/\alpha }+\theta ^{1/\alpha }\right) ^{\alpha
}\right) ^{1/\alpha +1}};
\end{equation*}

3) if $m=n-\psi (n),$ where $n\gg \psi (n)\gg \varphi (n),$ then 
\begin{equation*}
\lim_{n\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda (1-f_{\psi
(n)}(0))Z(m)}|\mathcal{H}(n,\varphi (n))\right] =\frac{1}{\left( 1+\lambda
\right) ^{\alpha +1}};
\end{equation*}

4) if $m=n-y\varphi (n),$ where $y\in (0,\infty ),$ then 
\begin{equation*}
\lim_{n\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda (1-f_{n-m}(0))Z(m)}| 
\mathcal{H}(n,\varphi (n))\right] =\sum_{j=1}^{\infty }\frac{\alpha \Gamma
\left( j+\alpha \right) }{j!\left( 1+\lambda \right) ^{\alpha +j}}yM^{\ast
j}(y^{-1/\alpha }),
\end{equation*} 
where $\Gamma (\cdot )$ is the standard Gamma-function and $M^{\ast j}(x)$
is the $j$-th convolution of $M(x)$ with itself;

5) if $m=n-\chi (n)$ where $n\gg \varphi (n)\gg \chi (n)\geq 0$ then 
\begin{equation*}
\lim_{m\rightarrow \infty }\mathbf{E}\left[ e^{-\lambda \left( 1-f_{\varphi
(n)}(0)\right) Z(m)}|\mathcal{H}(n,\varphi (n))\right] =\alpha
\int_{0}^{1}x^{\alpha -1}e^{-\lambda x}dx.
\end{equation*}

In particular, if $T\rightarrow \infty $ and $T=o\left(
(1-f_{n}(0))^{-1}\right) $ then
\begin{equation*}
\lim_{m\rightarrow \infty }\mathbf{P}\left( Z(n)<xT|0<Z(n)\leq T\right)
=x^{\alpha },\quad 0\leq x\leq 1.
\end{equation*}

\label{T_deviation} Let condition (\ref{MainAssump}) be valid for $\alpha
\in (0,1)$ and $\varphi (n),\ n=1,2,...,$ be a deterministic function
satisfying assumption (\ref{Def_phi}). Then
\begin{equation}
\mathbf{P}\left( \mathcal{H}(n,\varphi (n))\right) \sim \frac{1-f_{n}(0)}{ 
\alpha n}\frac{1}{\Gamma \left( 1+\alpha \right) }\varphi (n).
\label{LargeDeviation}
\end{equation}

\label{Rem1} Setting $T=\left( 1-f_{\varphi (n)}(0)\right) ^{-1}$ and
observing that
\begin{equation*}
\frac{L\left( 1/T\right) }{T^{\alpha }}=\left( 1-f_{\varphi (n)}(0)\right)
^{\alpha }L\left( 1-f_{\varphi (n)}(0)\right) \sim \frac{1}{\alpha \varphi
(n)}  \label{Repres1}
\end{equation*} 
as $n\rightarrow \infty $ by (\ref{SimpeForm}), we may rewrite (\ref 
{LargeDeviation}) as
\begin{equation}
\mathbf{P}\left( 0<Z(n)\leq T\right) \sim \frac{1-f_{n}(0)}{\alpha n}\frac{1 
}{\alpha \Gamma \left( 1+\alpha \right) }\frac{T^{\alpha }}{L\left(
1/T\right) }.  \label{ModifDevoation}
\end{equation}

\label{Rem2} If
\begin{equation}
f^{\prime }(1)=1,\quad \sigma ^{2}=f^{\prime \prime }(1)\in (0,\infty ),
\label{FinVariance}
\end{equation} 
then $L(x)\to \sigma ^{2}/2$ as $x\downarrow 0$ and (see, for instance,
\cite{AN72}, Ch.1, Sec. 9)
\begin{equation*}
1-f_{n}(0)\sim \frac{2}{\sigma ^{2}n},\quad n\rightarrow \infty .
\end{equation*} 
Hence it follows that if $n\gg \varphi (n)\rightarrow \infty $ then (\ref 
{LargeDeviation}) is replaced by
\begin{equation*}
\mathbf{P}\left( 0<Z(n)<T\right) \sim \frac{4}{\sigma ^{4}n^{2}}T,
\end{equation*} 
and is an evident corollary of the main result in \cite{NW2006}.

If, however, $\alpha=1$ and $\sigma^2=\infty$, then an asymptotic representation for $\mathbf{P}\left( 0<Z(n)\leq T\right)$ similar to (\ref{ModifDevoation}) is now know only for the case
\begin{equation}
\mathbf{P}\left( \xi \geq j\right) =\frac{\bar{L}(1/j)}{j^{2}},
\label{Alpha_1}
\end{equation} 
where $\bar{L}(z)$ is a function slowly varying at zero (see Remark 2 in \cite{VDK2025}).
 Since in the arguments to follow we use only the form of the right-hand side of (\ref{ModifDevoation}),
  one may check that all the statements of Theorem~\ref{T_Population_size} remain valid if either the condition (\ref{FinVariance}) or the conditin (\ref{Alpha_1}) is in force.

\label{T_reduced}(see \cite{VDK2025}) Let condition (\ref{MainAssump}) be
valid for $\alpha \in (0,1)$ and assumption (\ref{Def_phi}) hold true. Then,
for any $y\in (0,\infty )$ and any $j\geq 1$ 
\begin{equation}
\lim_{n\rightarrow \infty }\mathbf{P}\left( Z(n-y\varphi (n),n)=j|\mathcal{H} 
(n,\varphi (n))\right) =\frac{\alpha \Gamma \left( j+\alpha \right) }{j!} 
yM^{\ast j}(y^{-1/\alpha }).  \label{InfVar}
\end{equation}

\label{L_represent}Let condition (\ref{MainAssump}) be valid and $\rho >0$
be a fixed number. If $l\rightarrow \infty $ then the parameter $r$
satisfying the inequalities 
\begin{equation}
1-f_{r+1}(0)\leq 1-f_{l}^{\rho }(0)<1-f_{r}(0)  \label{R_inequality}
\end{equation} 
has the asymptotic representation 
\begin{equation}
r\sim l\rho ^{-\alpha },\quad l\rightarrow \infty .  \label{Assym_r}
\end{equation}
